  part def Controller {
    in attribute io_0 : Boolean;
    in attribute io_1 : Boolean;
    attribute servoAngle : Real := 90.0;
    attribute ledOn : Boolean := false;
    attribute previousBtn1 : Boolean := true;
    attribute previousBtn2 : Boolean := true;
    attribute moving : Boolean := false;
    attribute remainingMoveMs : Integer := 0;
    perform action tick {
      first start;
      then if moving and (remainingMoveMs <= 0) {
        first start;
        then assign moving := false;
        then assign ledOn := false;
      }
      then if ((io_0) and ((not previousBtn1)) and (((servoAngle) >= (0.0))) and (((servoAngle) < (180.0)))) {
        first start;
        then assign servoAngle := (if ((servoAngle + 30.0) >= (180.0)) ? 180.0 else servoAngle + 30.0);
        then assign moving := true;
        then assign remainingMoveMs := 2000;
        then assign ledOn := true;
      }
      then if ((io_1) and ((not previousBtn2)) and (((servoAngle) > (0.0))) and (((servoAngle) <= (180.0)))) {
        first start;
        then assign servoAngle := (if ((servoAngle - 30.0) <= (0.0)) ? 0.0 else servoAngle - 30.0);
        then assign moving := true;
        then assign remainingMoveMs := 2000;
        then assign ledOn := true;
      }
      then assign previousBtn1 := io_0;
      then assign previousBtn2 := io_1;
    }
    out attribute io_2 : Real = servoAngle;
    out attribute io_3 : Boolean = ledOn;
  }
  part system : Controller;
}
